package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdDuplicateException;

/**
 * Runs after {@link ValidateOwner} and before {@link BuildOwner}. Rejects the create with a 409 via
 * {@link OwnerHouseholdDuplicateException} when another owner already belongs to the same household
 * (same lastName and address — see {@link OwnerHousehold} for how that is compared).
 *
 * <p>The request may opt out of this rule by setting {@code sharesHousehold} true, which permits
 * creating a second owner in the same household; {@link AssignHousehold} then gives the new owner the
 * existing household's identifier.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerHouseholdDuplicateException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // opted in to sharing a household; skip the duplicate check
        }
        OwnerHousehold household = OwnerHousehold.of(request);
        for (Owner existing : ownerRepository.findAll()) {
            if (household.equals(OwnerHousehold.of(existing))) {
                throw new OwnerHouseholdDuplicateException(request.getLastName(), request.getAddress());
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown by {@link org.springframework.samples.petclinic.rest.function.owner.CheckOwnerHouseholdUnique}
 * when the owner being created has the same lastName and address (compared case-insensitively with
 * collapsed whitespace) as an existing owner and the request did not set {@code sharesHousehold} true.
 * Handled by {@link OwnerHouseholdDuplicateExceptionHandler}, which responds 409.
 */
public class OwnerHouseholdDuplicateException extends Exception {

    private final String lastName;

    private final String address;

    public OwnerHouseholdDuplicateException(String lastName, String address) {
        super("An owner with the same last name and address already exists: " + lastName + ", " + address);
        this.lastName = lastName;
        this.address = address;
    }

    public String getLastName() {
        return this.lastName;
    }

    public String getAddress() {
        return this.address;
    }
}
package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;
import java.util.Map;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

/**
 * Responds 409 with a JSON body whose {@code errors} array names {@code lastName} and {@code address}
 * when the owner being created shares a last name and address with an existing owner and the request
 * did not opt in via {@code sharesHousehold}.
 */
public class OwnerHouseholdDuplicateExceptionHandler {

    public void handle(@Parameter OwnerHouseholdDuplicateException ex,
            ObjectResponse<ResponseEntity<Map<String, Object>>> response) {
        Map<String, Object> body = Map.of("errors", List.of("lastName", "address"));
        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(body));
    }
}

